PREFIX : <https://w3id.org/rastro/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?name WHERE {
  {
    SELECT ?name (COUNT(DISTINCT ?t) AS ?n) WHERE {
      ?pulmon rdfs:label "Lung Neoplasms"@en .
      ?t :condition ?c . ?c :within ?pulmon .
      ?t :status ?st . FILTER(?st IN ("TERMINATED","WITHDRAWN"))
      ?t :sponsor ?s . ?s :industry true . ?s :name ?name .
    } GROUP BY ?name
  }
} ORDER BY DESC(?n) LIMIT 3
